import { motion } from "framer-motion";

const trainers = [
  {
    name: "Arjun Kumar",
    role: "Strength & Conditioning Coach",
    desc:
      "Specialising in resistance training, movement mechanics, and performance-focused workouts.",
    img: "https://images.unsplash.com/photo-1594737625785-cd2b6d7f1d8d",
  },
  {
    name: "Priya Menon",
    role: "Fitness Coach",
    desc:
      "Experienced in strength training, endurance development, and sustainable lifestyle fitness.",
    img: "https://images.unsplash.com/photo-1605296867304-46d5465a13f1",
  },
  {
    name: "Rahul Singh",
    role: "Conditioning Coach",
    desc:
      "Focused on fat loss, conditioning, and long-term fitness habit building.",
    img: "https://images.unsplash.com/photo-1618077360395-f3068be8e001",
  },
];

export default function Trainers() {
  return (
    <section
      id="trainers"
      className="scroll-mt-24 bg-gradient-to-b from-black via-zinc-900 to-black py-32 px-6"
    >
      <div className="max-w-7xl mx-auto">

        {/* HEADING */}
        <div className="mb-20 text-center">
          <h2 className="text-4xl md:text-5xl font-bold">
            Our <span className="text-red-600">Trainers</span>
          </h2>
          <p className="mt-6 text-gray-400 max-w-2xl mx-auto">
            Certified professionals delivering consistent coaching standards
            across all Bodyzeal Fitworks branches.
          </p>
        </div>

        {/* TRAINER CARDS */}
        <div className="grid gap-16 md:grid-cols-3">
          {trainers.map((t, i) => (
            <motion.div
              key={i}
              initial={{ opacity: 0, y: 40 }}
              whileInView={{ opacity: 1, y: 0 }}
              viewport={{ once: true }}
              transition={{ duration: 0.6, delay: i * 0.15 }}
              className="group text-center"
            >
              {/* IMAGE */}
              <div className="relative mx-auto w-48 h-48 rounded-full overflow-hidden border-4 border-red-600/30 group-hover:border-red-600 transition">
                <img
                  src={`${t.img}?auto=format&fit=crop&w=500&q=80`}
                  alt={t.name}
                  className="w-full h-full object-cover group-hover:scale-110 transition duration-500"
                />
              </div>

              {/* CONTENT */}
              <div className="mt-8 px-4">
                <h3 className="text-xl font-semibold">{t.name}</h3>
                <p className="text-red-500 text-sm mt-1">
                  {t.role}
                </p>

                <p className="mt-4 text-sm text-gray-400 leading-relaxed">
                  {t.desc}
                </p>
              </div>
            </motion.div>
          ))}
        </div>

        {/* FOOT NOTE */}
        <p className="mt-24 text-center text-sm text-gray-500 max-w-3xl mx-auto">
          All trainers follow the same coaching standards and training protocols
          across Bodyzeal Fitworks branches.
        </p>

      </div>
    </section>
  );
}
